SELECT * FROM (SELECT t.*, ROWNUM AS rowno FROM (SELECT h.id, h.fru_before fruBefore, h.fru_now fruNow, h.hardware_type hardwareType, h.fix_time fixTime, h.reason, h.description, h.create_time createTime, a.id assetId, a.name assetName, a.ip assetIp, a.ipmi_ip ipmiIp, a.asset_mode assetMode, g.name assetModeStr, m.name manufacturer FROM ASSET_HARDWARE_FIX h LEFT JOIN ASSET a on a.ID = h.ASSET_ID LEFT JOIN ASSET_MANUFACTURER m on m.id = a.MANUFACTURER_ID LEFT JOIN ASSET_MODE g on a.desk = g.code WHERE 1 = 1 and a.IS_DEL = 1
and a.name like concat(concat('%', #{assetName}), '%')
and h.hardware_type = #{hardwareType}
and a.desk = #{assetMode}
and h.FIX_TIME BETWEEN TO_DATE(#{startTime}, 'yyyy-MM-dd HH24:mi:ss') AND TO_DATE(#{endTime}, 'yyyy-MM-dd HH24:mi:ss')
and h.asset_id IN
NULL ) OR h.asset_id IN (#{id}
and a.org_id in
#{id}
ORDER BY h.CREATE_TIME DESC) t WHERE ROWNUM < #{end}) tt WHERE tt.rowno > #{start}

