SELECT * FROM (SELECT t.*, ROWNUM AS rowno FROM (SELECT h.id, h.fru_before fruBefore, h.fru_now fruNow, h.hardware_type hardwareType, h.fix_time fixTime, h.reason, h.description, h.create_time createTime, a.id assetId, a.name assetName, a.ip assetIp, a.ipmi_ip ipmiIp, a.asset_mode assetMode, decode(a.desk, 183,'服务器',42,'路由器',201,'交换机',263,'数据库',1831,'终端',1832,'小型机',1833,'工控机','未知' ) assetModeStr, decode(a.MANUFACTURER_ID, 0,'惠普',1,'IBM',2,'华为',3,'ORACLE',4,'思科',5,'MOXA',6,'研华','未知' ) manufacturer, decode(h.HARDWARE_TYPE,1,'CPU',2,'内存',3,'硬盘',4,'电源',5,'板卡',6,'风扇',7,'引擎',8,'CPU板',9,'IO板',10,'控制器',11,'稳压模块','未知')hardwareTypeStr FROM ASSET_HARDWARE_FIX h LEFT JOIN ASSET a on a.ID = h.ASSET_ID WHERE 1 = 1
and a.name like concat(concat('%', #{assetName}), '%')
and h.hardware_type = #{hardwareType}
and a.desk = #{assetMode}
and to_char(h.fix_time, 'yyyy-mm') = #{month}
and h.asset_id in
NULL ) OR h.asset_id IN (#{id}
ORDER BY h.CREATE_TIME DESC) t WHERE ROWNUM < #{end}) tt WHERE tt.rowno > #{start}
